      document.getElementById("xValue").value = "2";
      document.getElementById("yValue").value = "3";
      document.getElementById("upstream").value = "1";
      document.getElementById("tapeDepth").value = "6";
      document.getElementById("checkpointRate").value = "0.2";
      document.getElementById("learningRate2").value = "0.1";
