        highShare: s.highShare,
        cutoff: cutoff(),
        noiseLevel: noiseLevel(),
        diffusionTime: diffusionTime(),
        bandWidth: bandWidth(),
        waveletScale: waveletScale(),
        stateText: stateText.textContent.trim(),
