          signalPreset: signalPreset(),
          mode: mode(),
          viewSelect: view(),
          cutoff: String(cutoff()),
          noiseLevel: String(noiseLevel()),
          diffusionTime: String(diffusionTime()),
          bandWidth: String(bandWidth()),
